"""Record rendering.

Secret: how a list of records is rendered in each supported output format,
how requested field names are matched against record keys (case-insensitive,
with an optional prefix), and when a single record is shown vertically.
"""

import csv
import io
import json

from . import messages as _messages
from . import yaml_lite
from .errors import CliError

_FORMATS = ("table", "json", "csv", "yaml", "ids", "count")


def supported_formats():
    return list(_FORMATS)


def _cell(value):
    """Scalar text for table and CSV cells; arrays and objects become JSON."""
    if value is None:
        return ""
    if isinstance(value, (list, tuple, dict)):
        return json.dumps(value)
    return str(value)


def _table_rows(header, rows):
    widths = [max([len(h)] + [len(row[i]) for row in rows])
              for i, h in enumerate(header)]
    return "\n".join("  ".join(c.ljust(w) for c, w in zip(row, widths)).rstrip()
                     for row in [header] + rows)


def _table(records, fields):
    return _table_rows(list(fields),
                       [[_cell(r.get(f)) for f in fields] for r in records])


def _vertical(record, fields):
    """One record laid out as Field/Value pairs."""
    return _table_rows(["Field", "Value"], [[f, _cell(record.get(f))] for f in fields])


def _csv(records, fields):
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(fields)
    for record in records:
        writer.writerow([_cell(record.get(f)) for f in fields])
    return buffer.getvalue().rstrip("\n")


def _restrict(records, fields):
    return [{f: r.get(f) for f in fields} for r in records]


def _id_field(fields, available, prefix):
    for name in list(fields) + list(available):
        if name.casefold() == "id" or (prefix and name.casefold() == f"{prefix}_id".casefold()):
            return name
    return fields[0] if fields else None


def render(records, fields, fmt, prefix=None):
    """Render ``records`` (dicts) restricted to ``fields`` in format ``fmt``.

    Raises ``ValueError`` for an unsupported format.
    """
    fields = list(fields)
    records = list(records)
    if fmt == "table":
        if len(records) == 1:
            return _vertical(records[0], fields)
        return _table(records, fields)
    if fmt == "json":
        return json.dumps(_restrict(records, fields), indent=4)
    if fmt == "csv":
        return _csv(records, fields)
    if fmt == "yaml":
        return yaml_lite.dump_records(_restrict(records, fields))
    if fmt == "ids":
        key = _id_field(fields, [k for r in records for k in r], prefix)
        return " ".join(_cell(r.get(key)) for r in records)
    if fmt == "count":
        return str(len(records))
    raise ValueError(fmt)


def render_field(records, field, fmt):
    """Only the values of ``field``, one per line."""
    if fmt == "json":
        return "\n".join(json.dumps(r.get(field)) for r in records)
    if fmt == "count":
        return str(len(records))
    return "\n".join(_cell(r.get(field)) for r in records)


class Formatter:
    """Resolves ``--format``, ``--field`` and ``--fields`` for a command."""

    def __init__(self, fmt="table", field=None, fields=None, prefix=None,
                 default_fields=()):
        self.format = fmt or "table"
        self.field = field
        self.fields = fields
        self.prefix = prefix
        self.default_fields = list(default_fields)

    def _available(self, records):
        names = list(self.default_fields)
        for record in records:
            names.extend(record)
        return list(dict.fromkeys(names))

    def find_field(self, name, available):
        """Match ``name`` exactly, then case-insensitively, then with the
        prefix prepended. Raises ``CliError`` when nothing matches."""
        candidates = [name]
        if self.prefix and not name.casefold().startswith(f"{self.prefix}_".casefold()):
            candidates.append(f"{self.prefix}_{name}")
        for candidate in candidates:
            if candidate in available:
                return candidate
            folded = candidate.casefold()
            for key in available:
                if key.casefold() == folded:
                    return key
        raise CliError(_messages.invalid_field(name))

    def display(self, records):
        """Return the rendered text for ``records``."""
        records = list(records)
        available = self._available(records)
        if self.field:
            field = self.find_field(str(self.field), available)
            return render_field(records, field, self.format)
        if self.fields:
            requested = [f.strip() for f in str(self.fields).split(",") if f.strip()]
            fields = list(dict.fromkeys(self.find_field(f, available) for f in requested))
        else:
            fields = self.default_fields or available
        try:
            return render(records, fields, self.format, self.prefix)
        except ValueError:
            raise CliError(_messages.invalid_format(self.format, supported_formats()))


_MAPPING_FORMATS = ("list", "json", "yaml")


def supported_mapping_formats():
    return list(_MAPPING_FORMATS)


def render_mapping(mapping, fmt):
    """Render a single key/value mapping. Raises ``ValueError`` for an
    unsupported format."""
    if fmt == "list":
        width = max((len(k) for k in mapping), default=0)
        return "\n".join(f"{k.ljust(width)}  {v}" for k, v in mapping.items())
    if fmt == "json":
        return json.dumps(mapping)
    if fmt == "yaml":
        return "\n".join(["---"] + [f"{k}: {json.dumps(v)}" for k, v in mapping.items()])
    raise ValueError(fmt)
"""Alias registry.

Secret: the alias name syntax, how runtime aliases override file aliases,
when ``@all`` is registered automatically, how groups are expanded and
validated, and the order in which broadcast targets run.
"""

import json
import re

from . import messages as _messages
from .errors import CliError
from .suggest import suggest

_ALIAS_NAME = re.compile(r"^@[A-Za-z0-9_.\-]+$")
_RUNTIME_ENV = "APPCTL_RUNTIME_ALIAS"
ALL = "@all"
_AUTO_ALL = "Run command against every registered alias."


def is_alias_name(text):
    return isinstance(text, str) and bool(_ALIAS_NAME.match(text))


def _sort_key(name):
    return (name.casefold(), name)


def runtime_aliases(env):
    """Alias definitions from the runtime environment variable."""
    raw = env.get(_RUNTIME_ENV)
    if not raw:
        return {}
    try:
        decoded = json.loads(raw)
    except ValueError:
        return {}
    if not isinstance(decoded, dict):
        return {}
    result = {}
    for name, value in decoded.items():
        if not is_alias_name(name):
            continue
        if isinstance(value, list):
            result[name] = [str(v) for v in value if v is not None]
        elif isinstance(value, dict):
            result[name] = dict(value)
        elif value is None:
            result[name] = {}
    return result


class Target:
    """Resolution of an alias: either a connection or a group of aliases."""

    def __init__(self, name, connection=None, members=None):
        self.name = name
        self.connection = connection
        self.members = members

    def is_group(self):
        return self.members is not None


class AliasRegistry:
    def __init__(self, file_aliases, runtime=None):
        self._defs = dict(file_aliases)
        self._defs.update(runtime or {})
        if self._defs and ALL not in self._defs:
            self._defs[ALL] = _AUTO_ALL

    def names(self):
        return sorted(self._defs, key=_sort_key)

    def is_registered(self, name):
        return name in self._defs

    def definitions(self):
        return dict(self._defs)

    def definition(self, name):
        return self._defs.get(name)

    def _broadcast_members(self):
        return [name for name in self.names()
                if name != ALL and isinstance(self._defs[name], dict)]

    def resolve(self, name):
        """Return the ``Target`` for alias ``name`` or raise ``CliError``."""
        if name == ALL and not self._defs:
            raise CliError(_messages.alias_all_without_aliases())
        if name not in self._defs:
            raise CliError(_messages.alias_not_found(
                name, suggest(name, list(self._defs))))
        value = self._defs[name]
        if name == ALL and value == _AUTO_ALL:
            return Target(name, members=self._broadcast_members())
        if isinstance(value, list):
            members = list(dict.fromkeys(value))
            invalid = [m for m in members if m not in self._defs]
            if invalid:
                raise CliError(_messages.alias_group_invalid(name, invalid))
            return Target(name, members=members)
        return Target(name, connection=dict(value) if isinstance(value, dict) else {})
"""Archive extraction.

Secret: which archive types are recognised, which runtime facilities are
used to unpack them (and the fallback when the built-in tar.gz support
fails), and how unpacked files are merged into an existing directory.
"""

import os
import shutil
import tempfile

from . import messages as _messages
from . import process
from .errors import CliError

_ZIP = ".zip"
_TAR_GZ = ".tar.gz"


def archive_type(path):
    """``"zip"``, ``"tar.gz"`` or ``None`` for an unsupported file name."""
    name = str(path).lower()
    if name.endswith(_TAR_GZ):
        return "tar.gz"
    if name.endswith(_ZIP):
        return "zip"
    return None


def validate(archive):
    """Raise ``CliError`` unless ``archive`` is an existing supported archive."""
    if archive_type(archive) is None:
        raise CliError(_messages.unsupported_archive())
    if not os.path.isfile(archive):
        raise CliError(_messages.archive_not_found(archive))


def _reason(exc):
    return getattr(exc, "strerror", None) or str(exc) or type(exc).__name__


def _unpack_zip(archive, target):
    try:
        import zipfile
    except ImportError:
        raise CliError(_messages.zip_unavailable()) from None
    try:
        with zipfile.ZipFile(archive) as bundle:
            bundle.extractall(target)
    except (zipfile.BadZipFile, OSError, RuntimeError, ValueError,
            NotImplementedError, EOFError) as exc:
        raise CliError(_messages.archive_extraction_failed(archive, _reason(exc))) from None


def _unpack_tar_gz(archive, target, out):
    try:
        import tarfile
    except ImportError:
        tarfile = None
    if tarfile is not None:
        try:
            with tarfile.open(archive, "r:gz") as bundle:
                if hasattr(tarfile, "data_filter"):
                    bundle.extractall(target, filter="data")
                else:
                    bundle.extractall(target)
            return
        except (tarfile.TarError, OSError, EOFError, ValueError) as exc:
            reason = _reason(exc)
    else:
        reason = "tarfile is not available"
    out.warning(_messages.tarfile_fallback(reason))
    _reset(target)
    tar = shutil.which("tar")
    if tar is None:
        raise CliError(_messages.tar_unavailable())
    result = process.run([tar, "xzf", archive, "-C", target], out=out)
    if not result.succeeded:
        lines = result.stderr.strip().splitlines()
        raise CliError(_messages.archive_extraction_failed(
            archive, lines[0] if lines else f"tar exited with code {result.return_code}"))


def _reset(directory):
    shutil.rmtree(directory, ignore_errors=True)
    os.makedirs(directory, exist_ok=True)


def _writable(path):
    return os.access(path, os.W_OK)


def _copy_file(source, dest):
    if os.path.islink(source):
        os.symlink(os.readlink(source), dest)
    else:
        shutil.copyfile(source, dest)
        shutil.copymode(source, dest)


def copy_overwrite_files(source, dest, out):
    """Copy the tree below ``source`` into ``dest``, overwriting writable
    files. Every file that cannot be copied is reported as a warning; once
    all files have been processed a ``CliError`` is raised if any failed."""
    failed = []

    def walk(directory, relative):
        try:
            names = sorted(os.listdir(directory))
        except OSError:
            return
        for name in names:
            src = os.path.join(directory, name)
            rel = f"{relative}/{name}" if relative else name
            dst = os.path.join(dest, *rel.split("/"))
            if os.path.isdir(src) and not os.path.islink(src):
                if not os.path.isdir(dst):
                    try:
                        os.makedirs(dst)
                    except OSError:
                        failed.append(rel)
                        out.warning(_messages.unable_to_copy(rel))
                        continue
                walk(src, rel)
                continue
            exists = os.path.lexists(dst)
            try:
                if exists and (os.path.isdir(dst) or not _writable(dst)):
                    raise PermissionError(rel)
                if exists and os.path.islink(dst) != os.path.islink(src):
                    os.unlink(dst)
                elif exists and os.path.islink(src):
                    os.unlink(dst)
                _copy_file(src, dst)
            except OSError:
                failed.append(rel)
                out.warning(_messages.unable_to_copy(rel))

    os.makedirs(dest, exist_ok=True)
    walk(source, "")
    if failed:
        raise CliError(_messages.overwrite_failed())


def extract(archive, dest, out):
    """Extract a ``.zip`` or ``.tar.gz`` ``archive`` into directory ``dest``."""
    kind = archive_type(archive)
    if kind is None:
        raise CliError(_messages.unsupported_archive())
    validate(archive)
    staging = tempfile.mkdtemp(prefix="appctl-extract-")
    try:
        if kind == "zip":
            _unpack_zip(archive, staging)
        else:
            _unpack_tar_gz(archive, staging, out)
        copy_overwrite_files(staging, dest, out)
    finally:
        shutil.rmtree(staging, ignore_errors=True)
"""Convenience rewrites applied before dispatch.

Secret: which shortcut spellings are rewritten into canonical commands and
how — currently ``<command> --help`` becomes ``help <command>`` and a bare
``--version`` becomes ``cli version``.
"""

from . import tokens as _tokens


def _is_bare_flag(token, name):
    return token.is_option() and token.name == name and token.value is None


def _rewrite_version(items):
    if any(not t.is_option() for t in items):
        return items
    if not any(_is_bare_flag(t, "version") for t in items):
        return items
    kept = [t for t in items if not _is_bare_flag(t, "version")]
    return kept + [_tokens.positional("cli"), _tokens.positional("version")]


def _rewrite_help(items):
    if not any(_is_bare_flag(t, "help") for t in items):
        return items
    kept = [t for t in items if not _is_bare_flag(t, "help")]
    help_word = _tokens.positional("help")
    for index, token in enumerate(kept):
        if not token.is_option():
            return kept[:index] + [help_word] + kept[index:]
    return kept + [help_word]


def apply(items):
    """Return a new token list with all rewrites applied."""
    return _rewrite_help(_rewrite_version(list(items)))
"""Help and usage layout.

Secret: how help listings, command help pages and usage lines are laid out:
section order, column alignment and wording of the surrounding text.
"""

from .messages import program_name


def _columns(nodes):
    width = max((len(n.name) for n in nodes), default=0)
    return "\n".join(f"  {n.name.ljust(width)}  {n.description}".rstrip()
                     for n in nodes)


def _invocation(node):
    """``appctl <path> <synopsis>`` for one command."""
    words = [program_name(), node.path]
    if node.has_children() and not node.is_runnable():
        words.append("<command>")
    else:
        words.append(node.synopsis.text())
    return " ".join(w for w in words if w)


def top_level_help(tree):
    prog = program_name()
    return (
        f"usage: {prog} <command> [<subcommand>] [<args>] [--<flags>]\n"
        "\n"
        "Available commands:\n"
        "\n"
        f"{_columns(tree.root.children())}\n"
        "\n"
        f"See '{prog} help <command>' for more information on a specific command."
    )


def usage_line(node):
    return f"usage: {_invocation(node)}"


def composite_usage(node):
    lines = []
    for index, child in enumerate(node.children()):
        lead = "usage:" if index == 0 else "   or:"
        lines.append(f"{lead} {_invocation(child)}")
    lines.append("")
    lines.append(f"See '{program_name()} help {node.path} <command>' "
                 "for more information on a specific command.")
    return "\n".join(lines)


def command_help(node):
    sections = [("NAME", f"  {program_name()} {node.path}")]
    if node.description:
        sections.append(("DESCRIPTION", f"  {node.description}"))
    synopses = []
    if node.is_runnable():
        synopses.append(" ".join(
            w for w in (program_name(), node.path, node.synopsis.text()) if w))
    if node.has_children():
        synopses.append(f"{program_name()} {node.path} <command>")
    sections.append(("SYNOPSIS", "\n".join(f"  {s}" for s in synopses)))
    if node.alias:
        sections.append(("ALIAS", f"  {node.alias}"))
    defaults = node.defaults()
    if defaults:
        positional = set(node.synopsis.positional_names())
        sections.append(("DEFAULTS", "\n".join(
            f"  <{key}>: {value}" if key in positional else f"  --{key}: {value}"
            for key, value in defaults.items())))
    if node.has_children():
        sections.append(("SUBCOMMANDS", _columns(node.children())))
    return "\n\n".join(f"{title}\n\n{body}" for title, body in sections)

